use indexmap::IndexMap;
use petgraph::graph::{DiGraph, NodeIndex};
use petgraph::visit::EdgeRef;
use petgraph::Direction;
use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum NodeRole {
    EntryGate,
    BusinessLogic,
    ContractDefinition,
    DataRepository,
    ExternalBoundary,
    UtilityNoise,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum EdgeKind {
    Calls,
    ReferencesType,
    ImplementsInterface,
    MutatesState,
    ReadsProperty,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SemanticNode {
    pub symbol_id: String,
    pub display_name: String,
    pub file_path: String,
    pub byte_range: (usize, usize),
    pub line_range: (usize, usize),
    pub role: NodeRole,
    pub signature_hash: String,
    pub mutates_domain_state: bool,
    pub is_exported: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SemanticEdge {
    pub kind: EdgeKind,
    pub call_site_line: usize,
    pub is_dynamic_trace: bool,
}

pub struct CodebaseGraph {
    pub graph: DiGraph<SemanticNode, SemanticEdge>,
    pub symbol_to_index: IndexMap<String, NodeIndex>,
}

impl Default for CodebaseGraph {
    fn default() -> Self {
        Self::new()
    }
}

impl CodebaseGraph {
    pub fn new() -> Self {
        Self {
            graph: DiGraph::new(),
            symbol_to_index: IndexMap::new(),
        }
    }

    pub fn upsert_node(&mut self, node: SemanticNode) -> NodeIndex {
        if let Some(&idx) = self.symbol_to_index.get(&node.symbol_id) {
            self.graph[idx] = node;
            idx
        } else {
            let symbol_id = node.symbol_id.clone();
            let idx = self.graph.add_node(node);
            self.symbol_to_index.insert(symbol_id, idx);
            idx
        }
    }

    pub fn add_edge(
        &mut self,
        from_symbol: &str,
        to_symbol: &str,
        edge: SemanticEdge,
    ) -> Option<petgraph::graph::EdgeIndex> {
        let from_idx = *self.symbol_to_index.get(from_symbol)?;
        let to_idx = *self.symbol_to_index.get(to_symbol)?;
        Some(self.graph.add_edge(from_idx, to_idx, edge))
    }

    pub fn in_degree(&self, idx: NodeIndex) -> usize {
        self.graph.edges_directed(idx, Direction::Incoming).count()
    }

    pub fn out_degree_domain(&self, idx: NodeIndex) -> usize {
        self.graph
            .edges_directed(idx, Direction::Outgoing)
            .filter(|edge| {
                let target = &self.graph[edge.target()];
                target.role != NodeRole::UtilityNoise
            })
            .count()
    }
}

use crate::graph::{CodebaseGraph, NodeRole, SemanticNode};
use petgraph::graph::NodeIndex;
use serde::{Deserialize, Serialize};
use std::collections::HashSet;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PruningConfig {
    pub max_fan_in_utility_threshold: usize,
    pub max_corridor_depth: usize,
    pub include_type_only_edges: bool,
    pub ignore_path_prefixes: Vec<String>,
    pub ignore_symbol_substrings: Vec<String>,
}

impl Default for PruningConfig {
    fn default() -> Self {
        Self {
            max_fan_in_utility_threshold: 15,
            max_corridor_depth: 12,
            include_type_only_edges: true,
            ignore_path_prefixes: vec![
                "node_modules/".to_string(),
                "src/core/logger".to_string(),
                "src/core/telemetry".to_string(),
                "src/shared/utils".to_string(),
                "src/common/helpers".to_string(),
            ],
            ignore_symbol_substrings: vec![
                "Logger.".to_string(),
                "Metrics.".to_string(),
                "Tracer.".to_string(),
                "console.".to_string(),
            ],
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PrunedNodeRecord {
    pub symbol_id: String,
    pub reason: String,
    pub in_degree: usize,
    pub noise_score: f64,
}

pub struct PruneEvaluator<'a> {
    config: &'a PruningConfig,
    protected_symbols: HashSet<String>,
}

impl<'a> PruneEvaluator<'a> {
    pub fn new(config: &'a PruningConfig, protected_symbols: HashSet<String>) -> Self {
        Self {
            config,
            protected_symbols,
        }
    }

    pub fn compute_noise_score(&self, graph: &CodebaseGraph, idx: NodeIndex) -> f64 {
        let node = &graph.graph[idx];
        let in_deg = graph.in_degree(idx) as f64;
        let out_domain = (graph.out_degree_domain(idx).max(1)) as f64;
        let mutation_factor = if node.mutates_domain_state || node.role == NodeRole::DataRepository {
            0.1
        } else {
            1.0
        };
        (in_deg / out_domain) * mutation_factor
    }

    pub fn evaluate_node(
        &self,
        graph: &CodebaseGraph,
        idx: NodeIndex,
    ) -> Option<PrunedNodeRecord> {
        let node: &SemanticNode = &graph.graph[idx];

        if self.protected_symbols.contains(&node.symbol_id) {
            return None;
        }

        if node.role == NodeRole::EntryGate || node.role == NodeRole::ContractDefinition {
            return None;
        }

        for prefix in &self.config.ignore_path_prefixes {
            if node.file_path.starts_with(prefix) {
                return Some(PrunedNodeRecord {
                    symbol_id: node.symbol_id.clone(),
                    reason: format!("Matched ignored path prefix: {}", prefix),
                    in_degree: graph.in_degree(idx),
                    noise_score: 999.0,
                });
            }
        }

        for pattern in &self.config.ignore_symbol_substrings {
            if node.symbol_id.contains(pattern) || node.display_name.contains(pattern) {
                return Some(PrunedNodeRecord {
                    symbol_id: node.symbol_id.clone(),
                    reason: format!("Matched telemetry/logger pattern: {}", pattern),
                    in_degree: graph.in_degree(idx),
                    noise_score: 999.0,
                });
            }
        }

        let in_deg = graph.in_degree(idx);
        let out_domain = graph.out_degree_domain(idx);
        let noise_score = self.compute_noise_score(graph, idx);

        if node.role == NodeRole::UtilityNoise
            || (in_deg >= self.config.max_fan_in_utility_threshold
                && out_domain == 0
                && !node.mutates_domain_state)
        {
            return Some(PrunedNodeRecord {
                symbol_id: node.symbol_id.clone(),
                reason: format!(
                    "High fan-in pure utility (in_degree={}, out_domain=0)",
                    in_deg
                ),
                in_degree: in_deg,
                noise_score,
            });
        }

        None
    }
}

use crate::graph::{CodebaseGraph, EdgeKind, NodeRole, SemanticNode};
use crate::pruning::{PruneEvaluator, PrunedNodeRecord, PruningConfig};
use anyhow::{anyhow, Result};
use petgraph::algo::kosaraju_scc;
use petgraph::graph::NodeIndex;
use petgraph::visit::EdgeRef;
use petgraph::Direction;
use serde::{Deserialize, Serialize};
use std::collections::{HashMap, HashSet, VecDeque};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum SliceIntent {
    ReadFlow,
    MutateContract,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum GateStatus {
    Unlocked,
    Locked,
    Verified,
    Blocked,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum BlastRiskLevel {
    SafeInternal,
    Moderate,
    HighContagion,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ExternalDependent {
    pub symbol_id: String,
    pub file_path: String,
    pub call_site_line: usize,
    pub edge_kind: EdgeKind,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BlastRadiusReport {
    pub contagion_index: usize,
    pub risk_level: BlastRiskLevel,
    pub external_dependents: Vec<ExternalDependent>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CorridorGate {
    pub gate_index: usize,
    pub status: GateStatus,
    pub node: SemanticNode,
    pub upstream_contracts: Vec<String>,
    pub downstream_in_corridor: Vec<String>,
    pub blast_radius: BlastRadiusReport,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CorridorPlan {
    pub corridor_id: String,
    pub intent: SliceIntent,
    pub entry_gate_symbol: String,
    pub target_mutation_symbol: Option<String>,
    pub gates: Vec<CorridorGate>,
    pub pruned_nodes: Vec<PrunedNodeRecord>,
}

pub struct CorridorSlicer;

impl CorridorSlicer {
    pub fn build_corridor(
        graph: &CodebaseGraph,
        entry_symbol: &str,
        intent: SliceIntent,
        target_mutation_symbol: Option<&str>,
        config: &PruningConfig,
    ) -> Result<CorridorPlan> {
        let entry_idx = *graph
            .symbol_to_index
            .get(entry_symbol)
            .ok_or_else(|| anyhow!("Entry symbol '{}' not found in semantic graph", entry_symbol))?;

        let mut protected = HashSet::new();
        protected.insert(entry_symbol.to_string());
        if let Some(target) = target_mutation_symbol {
            protected.insert(target.to_string());
        }

        let evaluator = PruneEvaluator::new(config, protected);
        let mut pruned_records = Vec::new();
        let mut pruned_set = HashSet::new();

        // Step 1: Forward BFS from Entry Gate to isolate the active business corridor
        let mut active_corridor_nodes = HashSet::new();
        let mut queue = VecDeque::new();
        queue.push_back((entry_idx, 0usize));
        active_corridor_nodes.insert(entry_idx);

        while let Some((curr_idx, depth)) = queue.pop_front() {
            if depth >= config.max_corridor_depth {
                continue;
            }

            for edge in graph.graph.edges_directed(curr_idx, Direction::Outgoing) {
                if !config.include_type_only_edges && edge.weight().kind == EdgeKind::ReferencesType {
                    continue;
                }

                let next_idx = edge.target();
                if active_corridor_nodes.contains(&next_idx) || pruned_set.contains(&next_idx) {
                    continue;
                }

                if let Some(record) = evaluator.evaluate_node(graph, next_idx) {
                    pruned_set.insert(next_idx);
                    pruned_records.push(record);
                    continue;
                }

                active_corridor_nodes.insert(next_idx);
                queue.push_back((next_idx, depth + 1));
            }
        }

        // Step 2: Determine ordered sequence of nodes based on intent (Read vs Write)
        let ordered_indices = match intent {
            SliceIntent::ReadFlow => {
                Self::order_for_reading(graph, entry_idx, &active_corridor_nodes)
            }
            SliceIntent::MutateContract => {
                let target_sym = target_mutation_symbol.ok_or_else(|| {
                    anyhow!("target_mutation_symbol is required when intent is MutateContract")
                })?;
                let target_idx = *graph.symbol_to_index.get(target_sym).ok_or_else(|| {
                    anyhow!("Target mutation symbol '{}' not found in graph", target_sym)
                })?;
                active_corridor_nodes.insert(target_idx);
                Self::order_for_mutation(graph, target_idx, &active_corridor_nodes)
            }
        };

        // Step 3: Build Gates and calculate Blast Radius for each node
        let mut gates = Vec::with_capacity(ordered_indices.len());
        for (i, &node_idx) in ordered_indices.iter().enumerate() {
            let node = graph.graph[node_idx].clone();
            let blast_radius = Self::compute_blast_radius(graph, node_idx, &active_corridor_nodes);

            let upstream_contracts = graph
                .graph
                .edges_directed(node_idx, Direction::Outgoing)
                .filter_map(|e| {
                    let target = &graph.graph[e.target()];
                    if target.role == NodeRole::ContractDefinition {
                        Some(target.symbol_id.clone())
                    } else {
                        None
                    }
                })
                .collect();

            let downstream_in_corridor = graph
                .graph
                .edges_directed(node_idx, Direction::Incoming)
                .filter_map(|e| {
                    let source_idx = e.source();
                    if active_corridor_nodes.contains(&source_idx) {
                        Some(graph.graph[source_idx].symbol_id.clone())
                    } else {
                        None
                    }
                })
                .collect();

            gates.push(CorridorGate {
                gate_index: i,
                status: if i == 0 {
                    GateStatus::Unlocked
                } else {
                    GateStatus::Locked
                },
                node,
                upstream_contracts,
                downstream_in_corridor,
                blast_radius,
            });
        }

        let hash_input = format!("{}:{:?}:{:?}", entry_symbol, intent, target_mutation_symbol);
        let corridor_hash = blake3::hash(hash_input.as_bytes()).to_hex();
        let corridor_id = format!("cor_{}", &corridor_hash[..8]);

        Ok(CorridorPlan {
            corridor_id,
            intent,
            entry_gate_symbol: entry_symbol.to_string(),
            target_mutation_symbol: target_mutation_symbol.map(|s| s.to_string()),
            gates,
            pruned_nodes: pruned_records,
        })
    }

    fn order_for_reading(
        graph: &CodebaseGraph,
        entry_idx: NodeIndex,
        corridor_nodes: &HashSet<NodeIndex>,
    ) -> Vec<NodeIndex> {
        // Condense strongly connected components to handle recursive/cyclic calls deterministically
        let sccs = kosaraju_scc(&graph.graph);
        let mut ordered = Vec::new();
        let mut visited = HashSet::new();

        // Ensure entry_idx starts first
        ordered.push(entry_idx);
        visited.insert(entry_idx);

        // Iterate SCCs in reverse (topological order from roots to leaves in petgraph::kosaraju_scc)
        for scc in sccs.into_iter().rev() {
            for idx in scc {
                if corridor_nodes.contains(&idx) && !visited.contains(&idx) {
                    visited.insert(idx);
                    ordered.push(idx);
                }
            }
        }
        ordered
    }

    fn order_for_mutation(
        graph: &CodebaseGraph,
        target_idx: NodeIndex,
        corridor_nodes: &HashSet<NodeIndex>,
    ) -> Vec<NodeIndex> {
        // Backward slice from the mutated contract/symbol up to its callers inside the corridor
        let mut distance_map: HashMap<NodeIndex, usize> = HashMap::new();
        let mut queue = VecDeque::new();

        queue.push_back((target_idx, 0usize));
        distance_map.insert(target_idx, 0);

        while let Some((curr, dist)) = queue.pop_front() {
            for edge in graph.graph.edges_directed(curr, Direction::Incoming) {
                let caller = edge.source();
                if corridor_nodes.contains(&caller) && !distance_map.contains_key(&caller) {
                    distance_map.insert(caller, dist + 1);
                    queue.push_back((caller, dist + 1));
                }
            }
        }

        let mut impacted: Vec<(NodeIndex, usize)> = distance_map.into_iter().collect();
        impacted.sort_by_key(|&(_, dist)| dist);
        impacted.into_iter().map(|(idx, _)| idx).collect()
    }

    fn compute_blast_radius(
        graph: &CodebaseGraph,
        node_idx: NodeIndex,
        corridor_nodes: &HashSet<NodeIndex>,
    ) -> BlastRadiusReport {
        let mut external_dependents = Vec::new();

        for edge in graph.graph.edges_directed(node_idx, Direction::Incoming) {
            let caller_idx = edge.source();
            if !corridor_nodes.contains(&caller_idx) {
                let caller_node = &graph.graph[caller_idx];
                external_dependents.push(ExternalDependent {
                    symbol_id: caller_node.symbol_id.clone(),
                    file_path: caller_node.file_path.clone(),
                    call_site_line: edge.weight().call_site_line,
                    edge_kind: edge.weight().kind,
                });
            }
        }

        let contagion_index = external_dependents.len();
        let risk_level = match contagion_index {
            0 => BlastRiskLevel::SafeInternal,
            1..=3 => BlastRiskLevel::Moderate,
            _ => BlastRiskLevel::HighContagion,
        };

        BlastRadiusReport {
            contagion_index,
            risk_level,
            external_dependents,
        }
    }
}
